/* f77int2.c -- generated by runtime/s370/port.py from runtime/libf77.c,
 * with f77rt.c: part 2 of the COMPLEX primitives and
 * the specific intrinsics passed as arguments. */
#include <math.h>
#include "f77rt.h"

/* C89 has neither trunc nor round; libc370 is C89. */
static double fio_trunc(double v) { return v < 0.0 ? ceil(v) : floor(v); }
static double fio_round(double v) { return v < 0.0 ? ceil(v - 0.5) : floor(v + 0.5); }
#define trunc fio_trunc
#define round fio_round

/* A long value cut to short, its high word: what the compiled code
 * makes of a REAL function's long result. */
static float fio_cut(double v) { union { double d; float f[2]; } u; u.d = v; return u.f[0]; }

static double fio_zmod(double re, double im) {
    return f77m_zabs(re, im);
}

void f77_csin(float *out, float re, float im) {
    double k[2];
    if (f77k_sin(re, im, k, 0, 1)) { out[0] = (float)k[0]; out[1] = (float)k[1]; return; }
    out[0] = (float)(sin((double)re) * cosh((double)im));
    out[1] = (float)(cos((double)re) * sinh((double)im));
}
void f77_ccos(float *out, float re, float im) {
    double k[2];
    if (f77k_sin(re, im, k, 1, 1)) { out[0] = (float)k[0]; out[1] = (float)k[1]; return; }
    out[0] = (float)(cos((double)re) * cosh((double)im));
    out[1] = (float)(-sin((double)re) * sinh((double)im));
}

int f77_index(const char *a, int la, const char *b, int lb);

/* --- specific intrinsics as actual arguments ---------------------------
 *
 * F77 15.9.3 lets a specific intrinsic name be passed to a dummy
 * procedure; the compiler lowers intrinsics inline, so these are the
 * by-reference copies it passes the address of. */
int    f77i_iabs(int *x)              { return *x < 0 ? -*x : *x; }
float  f77i_abs(float *x)             { return *x < 0 ? -*x : *x; }
double f77i_dabs(double *x)           { return *x < 0 ? -*x : *x; }
float  f77i_sqrt(float *x)            { return fio_cut(f77f_sqrt((double)*x)); }
double f77i_dsqrt(double *x)          { return f77f_dsqrt(*x); }
float  f77i_exp(float *x)             { return fio_cut(f77f_exp((double)*x)); }
double f77i_dexp(double *x)           { return f77f_dexp(*x); }
float  f77i_alog(float *x)            { return fio_cut(f77f_log((double)*x)); }
double f77i_dlog(double *x)           { return f77f_dlog(*x); }
float  f77i_alog10(float *x)          { return fio_cut(f77f_log10((double)*x)); }
double f77i_dlog10(double *x)         { return f77f_dlog10(*x); }
float  f77i_sin(float *x)             { return fio_cut(f77f_sin((double)*x)); }
double f77i_dsin(double *x)           { return f77f_dsin(*x); }
